package com.moodtools.hub

internal object LauncherTranslationChunk7 {
    val entries = mapOf(
        "Removing the BlackBox installation and its virtual identity." to arrayOf("Tinatanggal ang BlackBox installation at ang virtual identity nito.", "BlackBox \uC124\uCE58\uC640 \uADF8 \uAC00\uC0C1 ID\uB97C \uC81C\uAC70\uD569\uB2C8\uB2E4.", "BlackBox \u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3068\u305D\u306E\u4EEE\u60F3ID\u3092\u524A\u9664\u3057\u3066\u3044\u307E\u3059\u3002", "\u6B63\u5728\u79FB\u9664 BlackBox \u5B89\u88C5\u53CA\u5176\u865A\u62DF\u8EAB\u4EFD\u3002", "Eliminando la instalaci\u00F3n de BlackBox y su identidad virtual.", "\u0110ang x\u00F3a c\u00E0i \u0111\u1EB7t BlackBox v\u00E0 danh t\u00EDnh \u1EA3o c\u1EE7a n\u00F3.", "Menghapus instalasi BlackBox dan identitas virtualnya.", "Removendo a instala\u00E7\u00E3o do BlackBox e sua identidade virtual.", "إزالة تثبيت BlackBox وهويته الافتراضية."),
        "Repair shell in place" to arrayOf("Inaayos ang shell sa lugar", "\uC81C\uC790\uB9AC\uC5D0 \uC178 \uC218\uB9AC", "\u30B7\u30A7\u30EB\u306E\u4FEE\u5FA9\u3092\u5B9F\u884C\u4E2D", "\u4FEE\u590D\u5C31\u5730\u7684 shell", "Reparaci\u00F3n de shell en su lugar", "S\u1EEDa ch\u1EEFa shell t\u1EA1i ch\u1ED7", "Memperbaiki shell di tempat", "Reparo de shell em andamento", "إصلاح قذيفة في مكانها"),
        "Resetting the installed game to a fresh state." to arrayOf("Ire-reset ang na-install na laro sa bagong estado.", "\uC124\uCE58\uB41C \uAC8C\uC784\uC744 \uCD08\uAE30 \uC0C1\uD0DC\uB85C \uC7AC\uC124\uC815\uD569\uB2C8\uB2E4.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u30B2\u30FC\u30E0\u3092\u521D\u671F\u72B6\u614B\u306B\u30EA\u30BB\u30C3\u30C8\u3057\u3066\u3044\u307E\u3059\u3002", "\u5C06\u5DF2\u5B89\u88C5\u7684\u6E38\u620F\u91CD\u7F6E\u4E3A\u521D\u59CB\u72B6\u6001\u3002", "Restableciendo el juego instalado a un estado nuevo.", "\u0110\u1EB7t l\u1EA1i tr\u00F2 ch\u01A1i \u0111\u00E3 c\u00E0i \u0111\u1EB7t v\u1EC1 tr\u1EA1ng th\u00E1i m\u1EDBi.", "Mengatur ulang game yang terinstal ke kondisi awal.", "Resetando o jogo instalado para um estado novo.", "إعادة ضبط اللعبة المثبتة إلى حالة جديدة."),
        "Restart Jester Mods and try again." to arrayOf("I-restart ang Jester Mods at subukang muli.", "Jester Mods\uB97C \uC7AC\uC2DC\uC791\uD558\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC2ED\uC2DC\uC624.", "Jester Mods \u3092\u518D\u8D77\u52D5\u3057\u3066\u3001\u518D\u5EA6\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u91CD\u542F Jester Mods \u5E76\u91CD\u8BD5\u3002", "Reinicie Jester Mods e intente de nuevo.", "Kh\u1EDFi \u0111\u1ED9ng l\u1EA1i Jester Mods v\u00E0 th\u1EED l\u1EA1i.", "Mulai ulang Jester Mods dan coba lagi.", "Reinicie o Jester Mods e tente novamente.", "أعد تشغيل Jester Mods وحاول مرة أخرى."),
        "Restart Jester Mods and try the selection again." to arrayOf("I-restart ang Jester Mods at subukang muli ang seleksyon.", "Jester Mods\uB97C \uC7AC\uC2DC\uC791\uD558\uACE0 \uC120\uD0DD\uC744 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC2ED\uC2DC\uC624.", "Jester Mods \u3092\u518D\u8D77\u52D5\u3057\u3066\u3001\u518D\u5EA6\u9078\u629E\u3092\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u91CD\u542F Jester Mods \u5E76\u518D\u6B21\u5C1D\u8BD5\u9009\u62E9\u3002", "Reinicie Jester Mods e intente la selecci\u00F3n nuevamente.", "Kh\u1EDFi \u0111\u1ED9ng l\u1EA1i Jester Mods v\u00E0 th\u1EED ch\u1ECDn l\u1EA1i.", "Mulai ulang Jester Mods dan coba pemilihan lagi.", "Reinicie o Jester Mods e tente a sele\u00E7\u00E3o novamente.", "أعد تشغيل Jester Mods وحاول التحديد مرة أخرى."),
        "Restart Jester Mods or unlock it again, then retry." to arrayOf("I-restart ang Jester Mods o i-unlock muli ito, tapos subukang muli.", "Jester Mods\uB97C \uC7AC\uC2DC\uC791\uD558\uAC70\uB098 \uB2E4\uC2DC \uC7A0\uAE08\uC744 \uD574\uC81C\uD55C \uD6C4 \uC7AC\uC2DC\uB3C4\uD558\uC2ED\uC2DC\uC624.", "Jester Mods \u3092\u518D\u8D77\u52D5\u3059\u308B\u304B\u518D\u5EA6\u30ED\u30C3\u30AF\u89E3\u9664\u3057\u3066\u304B\u3089\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u91CD\u542F Jester Mods \u6216\u91CD\u65B0\u89E3\u9501\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Reinicie Jester Mods o desbloqu\u00E9elo nuevamente, luego intente de nuevo.", "Kh\u1EDFi \u0111\u1ED9ng l\u1EA1i Jester Mods ho\u1EB7c m\u1EDF kh\u00F3a l\u1EA1i, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Mulai ulang Jester Mods atau buka kuncinya lagi, lalu coba kembali.", "Reinicie o Jester Mods ou desbloqueie novamente, e ent\u00E3o tente novamente.", "أعد تشغيل Jester Mods أو افتحه مرة أخرى، ثم أعد المحاولة."),
        "Restore the original game before changing this device to {0}." to arrayOf("Ibalik ang orihinal na laro bago baguhin ang device na ito sa {0}.", "\uC774 \uC7A5\uCE58\uB97C {0}(\uC73C)\uB85C \uBCC0\uACBD\uD558\uAE30 \uC804\uC5D0 \uC6D0\uB798 \uAC8C\uC784\uC744 \uBCF5\uC6D0\uD558\uC2ED\uC2DC\uC624.", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3092 {0} \u306B\u5909\u66F4\u3059\u308B\u524D\u306B\u3001\u5143\u306E\u30B2\u30FC\u30E0\u3092\u5FA9\u5143\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728\u5C06\u6B64\u8BBE\u5907\u66F4\u6539\u4E3A {0} \u524D\u6062\u590D\u539F\u59CB\u6E38\u620F\u3002", "Restaure el juego original antes de cambiar este dispositivo a {0}.", "Kh\u00F4i ph\u1EE5c tr\u00F2 ch\u01A1i g\u1ED1c tr\u01B0\u1EDBc khi thay \u0111\u1ED5i thi\u1EBFt b\u1ECB n\u00E0y th\u00E0nh {0}.", "Pulihkan game asli sebelum mengubah perangkat ini ke {0}.", "Restaure o jogo original antes de mudar este dispositivo para {0}.", "قم باستعادة اللعبة الأصلية قبل تغيير هذا الجهاز إلى {0}."),
        "Reusing the trusted package already saved on this device." to arrayOf("Inuulit ang paggamit ng trusted package na naka-save na sa device na ito.", "\uC774 \uC7A5\uCE58\uC5D0 \uC774\uBBF8 \uC800\uC7A5\uB41C \uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uD328\uD0A4\uC9C0\uB97C \uC7AC\uC0AC\uC6A9\uD569\uB2C8\uB2E4.", "\u65E2\u306B\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u306B\u4FDD\u5B58\u3055\u308C\u3066\u3044\u308B\u4FE1\u983C\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u518D\u5229\u7528\u3057\u3066\u3044\u307E\u3059\u3002", "\u91CD\u65B0\u4F7F\u7528\u5DF2\u4FDD\u5B58\u5728\u6B64\u8BBE\u5907\u4E0A\u7684\u53D7\u4FE1\u4EFB\u5305\u3002", "Reutilizando el paquete confiable ya guardado en este dispositivo.", "T\u00E1i s\u1EED d\u1EE5ng g\u00F3i tin c\u1EADy \u0111\u00E3 \u0111\u01B0\u1EE3c l\u01B0u tr\u1EEF tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y.", "Menggunakan kembali paket tepercaya yang sudah disimpan di perangkat ini.", "Reutilizando o pacote confi\u00E1vel j\u00E1 salvo neste dispositivo.", "إعادة استخدام الحزمة الموثوقة المحفوظة بالفعل على هذا الجهاز."),
        "Review the Android replacement steps before continuing." to arrayOf("Suriin ang mga hakbang sa pagpapalit ng Android bago magpatuloy.", "\uACC4\uC18D\uD558\uAE30 \uC804\uC5D0 Android \uAD50\uCCB4 \uB2E8\uACC4\uB97C \uAC80\uD1A0\uD558\uC2ED\uC2DC\uC624.", "\u7D9A\u884C\u3059\u308B\u524D\u306B\u3001Android \u306E\u7F6E\u63DB\u624B\u9806\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u7EE7\u7EED\u4E4B\u524D\u8BF7\u67E5\u770B Android \u66FF\u6362\u6B65\u9AA4\u3002", "Revise los pasos de reemplazo de Android antes de continuar.", "Xem l\u1EA1i c\u00E1c b\u01B0\u1EDBc thay th\u1EBF Android tr\u01B0\u1EDBc khi ti\u1EBFp t\u1EE5c.", "Tinjau langkah-langkah penggantian Android sebelum melanjutkan.", "Revise os passos de substitui\u00E7\u00E3o do Android antes de continuar.", "راجع خطوات استبدال Android قبل المتابعة."),
        "Reviewing update" to arrayOf("Sinusuri ang update", "\uC5C5\uB370\uC774\uD2B8 \uAC80\uD1A0", "\u66F4\u65B0\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u67E5\u770B\u66F4\u65B0", "Revisando actualizaci\u00F3n", "\u0110ang xem x\u00E9t c\u1EADp nh\u1EADt", "Meninjau pembaruan", "Revisando atualiza\u00E7\u00E3o", "مراجعة التحديث"),
        "Root access is required to continue." to arrayOf("Kinakailangan ang root access bago magpatuloy.", "\uACC4\uC18D\uD558\uB824\uBA74 \uB8E8\uD2B8 \uC561\uC138\uC2A4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", "\u7D9A\u884C\u3059\u308B\u306B\u306F root \u30A2\u30AF\u30BB\u30B9\u304C\u5FC5\u8981\u3067\u3059\u3002", "\u7EE7\u7EED\u9700\u8981\u83B7\u53D6 root \u6743\u9650\u3002", "Se requiere acceso root para continuar.", "C\u1EA7n quy\u1EC1n truy c\u1EADp root \u0111\u1EC3 ti\u1EBFp t\u1EE5c.", "Akses root diperlukan untuk melanjutkan.", "Acesso root \u00E9 necess\u00E1rio para continuar.", "مطلوب الوصول إلى الجذر للمتابعة."),
        "Search add-on history" to arrayOf("Hanapin ang kasaysayan ng add-on", "\uC560\uB4DC\uC628 \uAE30\uB85D \uAC80\uC0C9", "\u30A2\u30C9\u30AA\u30F3\u5C65\u6B74\u3092\u691C\u7D22", "\u641C\u7D22\u63D2\u4EF6\u5386\u53F2", "Buscar historial de complementos", "T\u00ECm ki\u1EBFm l\u1ECBch s\u1EED ti\u1EC7n \u00EDch b\u1ED5 sung", "Cari riwayat add-on", "Pesquisar hist\u00F3rico de complementos", "البحث في تاريخ الوظيفة الإضافية"),
        "Search launcher history" to arrayOf("Hanapin ang kasaysayan ng launcher", "\uB7F0\uCC98 \uAE30\uB85D \uAC80\uC0C9", "\u30E9\u30F3\u30C1\u30E3\u30FC\u5C65\u6B74\u3092\u691C\u7D22", "\u641C\u7D22\u542F\u52A8\u5668\u5386\u53F2", "Buscar historial del lanzador", "T\u00ECm ki\u1EBFm l\u1ECBch s\u1EED tr\u00ECnh kh\u1EDFi ch\u1EA1y", "Cari riwayat peluncur", "Pesquisar hist\u00F3rico do launcher", "البحث في تاريخ قاذفة"),
        "Secure connection failed" to arrayOf("Nabigong kumonekta nang ligtas", "\uBCF4\uC548 \uC5F0\uACB0 \uC2E4\uD328", "\u5B89\u5168\u306A\u63A5\u7D9A\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u5B89\u5168\u8FDE\u63A5\u5931\u8D25", "Conexi\u00F3n segura fallida", "K\u1EBFt n\u1ED1i b\u1EA3o m\u1EADt th\u1EA5t b\u1EA1i", "Koneksi aman gagal", "Falha na conex\u00E3o segura", "فشل الاتصال الآمن"),
        "Secure download started" to arrayOf("Nagsimula ang ligtas na pag-download", "\uBCF4\uC548 \uB2E4\uC6B4\uB85C\uB4DC \uC2DC\uC791\uB428", "\u5B89\u5168\u306A\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u958B\u59CB\u3057\u307E\u3057\u305F", "\u5B89\u5168\u4E0B\u8F7D\u5DF2\u5F00\u59CB", "Descarga segura iniciada", "B\u1EAFt \u0111\u1EA7u t\u1EA3i xu\u1ED1ng b\u1EA3o m\u1EADt", "Unduhan aman dimulai", "Download seguro iniciado", "بدأ التنزيل الآمن"),
        "Setup cancelled before Android changed the package" to arrayOf("Kinansela ang setup bago binago ng Android ang package", "Android\uAC00 \uD328\uD0A4\uC9C0\uB97C \uBCC0\uACBD\uD558\uAE30 \uC804\uC5D0 \uC124\uCE58 \uCDE8\uC18C\uB428", "Android \u304C\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u5909\u66F4\u3059\u308B\u524D\u306B\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u304C\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u5728 Android \u66F4\u6539\u5B89\u88C5\u5305\u4E4B\u524D\u53D6\u6D88\u4E86\u5B89\u88C5", "Configuraci\u00F3n cancelada antes de que Android cambiara el paquete", "C\u00E0i \u0111\u1EB7t b\u1ECB h\u1EE7y tr\u01B0\u1EDBc khi Android thay \u0111\u1ED5i g\u00F3i", "Pengaturan dibatalkan sebelum Android mengubah paket", "Configura\u00E7\u00E3o cancelada antes que o Android alterasse o pacote", "تم إلغاء الإعداد قبل أن يقوم Android بتغيير الحزمة"),
        "Setup cancelled by the user" to arrayOf("Kinansela ang setup ng gumagamit", "\uC0AC\uC6A9\uC790\uAC00 \uC124\uCE58\uB97C \uCDE8\uC18C\uD568", "\u30E6\u30FC\u30B6\u30FC\u306B\u3088\u3063\u3066\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u304C\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u7528\u6237\u53D6\u6D88\u4E86\u5B89\u88C5", "Configuraci\u00F3n cancelada por el usuario", "C\u00E0i \u0111\u1EB7t b\u1ECB h\u1EE7y b\u1EDFi ng\u01B0\u1EDDi d\u00F9ng", "Pengaturan dibatalkan oleh pengguna", "Configura\u00E7\u00E3o cancelada pelo usu\u00E1rio", "تم إلغاء الإعداد من قبل المستخدم"),
        "Setup package couldn't be verified" to arrayOf("Hindi ma-verify ang setup package", "\uC124\uCE58 \uD328\uD0A4\uC9C0\uB97C \uD655\uC778\uD560 \uC218 \uC5C6\uC74C", "\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u5B89\u88C5\u5305\u65E0\u6CD5\u9A8C\u8BC1", "No se pudo verificar el paquete de configuraci\u00F3n", "Kh\u00F4ng th\u1EC3 x\u00E1c minh g\u00F3i c\u00E0i \u0111\u1EB7t", "Paket pengaturan tidak dapat diverifikasi", "Pacote de configura\u00E7\u00E3o n\u00E3o p\u00F4de ser verificado", "لا يمكن التحقق من حزمة الإعداد"),
        "Shell verified and ready" to arrayOf("Na-verify ang shell at handa na", "\uC178 \uD655\uC778 \uC644\uB8CC \uBC0F \uC900\uBE44\uB428", "\u30B7\u30A7\u30EB\u304C\u78BA\u8A8D\u3055\u308C\u3001\u6E96\u5099\u5B8C\u4E86\u3067\u3059", "Shell \u5DF2\u9A8C\u8BC1\u5E76\u51C6\u5907\u5C31\u7EEA", "Shell verificado y listo", "Shell \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh v\u00E0 s\u1EB5n s\u00E0ng", "Shell diverifikasi dan siap", "Shell verificado e pronto", "تم التحقق من القشرة وجاهزة"),
        "Showing saved history. Try again when you're online to check for updates." to arrayOf("Ipinapakita ang na-save na kasaysayan. Subukang muli kapag online ka upang tingnan ang mga update.", "\uC800\uC7A5\uB41C \uAE30\uB85D \uD45C\uC2DC \uC911. \uC628\uB77C\uC778 \uC0C1\uD0DC\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC5EC \uC5C5\uB370\uC774\uD2B8\uB97C \uD655\uC778\uD558\uC138\uC694.", "\u4FDD\u5B58\u3055\u308C\u305F\u5C65\u6B74\u3092\u8868\u793A\u3057\u3066\u3044\u307E\u3059\u3002\u66F4\u65B0\u3092\u78BA\u8A8D\u3059\u308B\u306B\u306F\u3001\u30AA\u30F3\u30E9\u30A4\u30F3\u6642\u306B\u518D\u5EA6\u304A\u8A66\u3057\u304F\u3060\u3055\u3044\u3002", "\u663E\u793A\u4FDD\u5B58\u7684\u5386\u53F2\u8BB0\u5F55\u3002\u5F53\u4F60\u5728\u7EBF\u65F6\u91CD\u8BD5\u4EE5\u68C0\u67E5\u66F4\u65B0\u3002", "Mostrando historial guardado. Intenta de nuevo cuando est\u00E9s en l\u00EDnea para buscar actualizaciones.", "Hi\u1EC3n th\u1ECB l\u1ECBch s\u1EED \u0111\u00E3 l\u01B0u. Th\u1EED l\u1EA1i khi b\u1EA1n tr\u1EF1c tuy\u1EBFn \u0111\u1EC3 ki\u1EC3m tra c\u00E1c b\u1EA3n c\u1EADp nh\u1EADt.", "Menampilkan riwayat yang disimpan. Coba lagi saat online untuk memeriksa pembaruan.", "Mostrando hist\u00F3rico salvo. Tente novamente quando estiver online para verificar atualiza\u00E7\u00F5es.", "إظهار التاريخ المحفوظ. حاول مرة أخرى عندما تكون متصلاً بالإنترنت للتحقق من وجود تحديثات."),
        "Showing {0} of {1} add-ons" to arrayOf("Ipinapakita ang {0} sa {1} add-on", "{1}\uAC1C\uC758 \uC560\uB4DC\uC628 \uC911 {0}\uAC1C \uD45C\uC2DC", "{1} \u306E\u3046\u3061 {0} \u306E\u30A2\u30C9\u30AA\u30F3\u3092\u8868\u793A\u3057\u3066\u3044\u307E\u3059", "\u663E\u793A {0} \u4E2A\u5171 {1} \u4E2A\u63D2\u4EF6", "Mostrando {0} de {1} complementos", "Hi\u1EC3n th\u1ECB {0} trong t\u1ED5ng s\u1ED1 {1} ti\u1EC7n \u00EDch b\u1ED5 sung", "Menampilkan {0} dari {1} add-on", "Mostrando {0} de {1} complementos", "جارٍ عرض {0} من إجمالي {1} من الإضافات"),
        "Showing {0} of {1} releases" to arrayOf("Ipinapakita ang {0} sa {1} release", "{1}\uAC1C\uC758 \uB9B4\uB9AC\uC2A4 \uC911 {0}\uAC1C \uD45C\uC2DC", "{1} \u306E\u3046\u3061 {0} \u306E\u30EA\u30EA\u30FC\u30B9\u3092\u8868\u793A\u3057\u3066\u3044\u307E\u3059", "\u663E\u793A {0} \u4E2A\u5171 {1} \u4E2A\u53D1\u5E03\u7248\u672C", "Mostrando {0} de {1} lanzamientos", "Hi\u1EC3n th\u1ECB {0} trong t\u1ED5ng s\u1ED1 {1} phi\u00EAn b\u1EA3n ph\u00E1t h\u00E0nh", "Menampilkan {0} dari {1} rilis", "Mostrando {0} de {1} lan\u00E7amentos", "يتم عرض {0} من {1} إصدار"),
        "Started protected package setup" to arrayOf("Sinimulan ang setup ng protektadong package", "\uBCF4\uD638\uB41C \uD328\uD0A4\uC9C0 \uC124\uCE58 \uC2DC\uC791", "\u4FDD\u8B77\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3092\u958B\u59CB\u3057\u307E\u3057\u305F", "\u5DF2\u5F00\u59CB\u53D7\u4FDD\u62A4\u7684\u5B89\u88C5\u5305\u5B89\u88C5", "Se inici\u00F3 la configuraci\u00F3n del paquete protegido", "B\u1EAFt \u0111\u1EA7u c\u00E0i \u0111\u1EB7t g\u00F3i \u0111\u01B0\u1EE3c b\u1EA3o v\u1EC7", "Memulai pengaturan paket yang dilindungi", "Iniciada configura\u00E7\u00E3o de pacote protegido", "بدأ إعداد الحزمة المحمية"),
        "Started secure add-on update check" to arrayOf("Sinimulan ang ligtas na pagsuri ng update ng add-on", "\uBCF4\uC548 \uC560\uB4DC\uC628 \uC5C5\uB370\uC774\uD2B8 \uD655\uC778 \uC2DC\uC791", "\u5B89\u5168\u306A\u30A2\u30C9\u30AA\u30F3\u66F4\u65B0\u30C1\u30A7\u30C3\u30AF\u3092\u958B\u59CB\u3057\u307E\u3057\u305F", "\u5DF2\u5F00\u59CB\u5B89\u5168\u63D2\u4EF6\u66F4\u65B0\u68C0\u67E5", "Se inici\u00F3 la verificaci\u00F3n de actualizaci\u00F3n segura del complemento", "B\u1EAFt \u0111\u1EA7u ki\u1EC3m tra c\u1EADp nh\u1EADt ti\u1EC7n \u00EDch b\u1ED5 sung b\u1EA3o m\u1EADt", "Memulai pemeriksaan pembaruan add-on aman", "Iniciada verifica\u00E7\u00E3o de atualiza\u00E7\u00E3o segura de complementos", "بدأ التحقق من تحديث الوظيفة الإضافية الآمنة"),
        "Stopped waiting for Android" to arrayOf("Itinigil ang paghihintay sa Android", "Android \uB300\uAE30 \uC911\uC9C0", "Android \u306E\u5F85\u6A5F\u3092\u505C\u6B62\u3057\u307E\u3057\u305F", "\u505C\u6B62\u7B49\u5F85 Android", "Se dej\u00F3 de esperar a Android", "Ng\u1EEBng ch\u1EDD Android", "Berhenti menunggu Android", "Parou de esperar pelo Android", "توقفت عن انتظار Android"),
        "Stopped waiting for Android installer" to arrayOf("Itinigil ang paghihintay sa installer ng Android", "Android \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8 \uB300\uAE30 \uC911\uC9C0", "Android \u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u306E\u5F85\u6A5F\u3092\u505C\u6B62\u3057\u307E\u3057\u305F", "\u505C\u6B62\u7B49\u5F85 Android \u5B89\u88C5\u7A0B\u5E8F", "Se dej\u00F3 de esperar al instalador de Android", "Ng\u1EEBng ch\u1EDD tr\u00ECnh c\u00E0i \u0111\u1EB7t Android", "Berhenti menunggu penginstal Android", "Parou de esperar pelo instalador do Android", "توقفت عن انتظار برنامج تثبيت Android"),
        "Stopping safely" to arrayOf("Maingat na itinitigil", "\uC548\uC804\uD558\uAC8C \uC885\uB8CC \uC911", "\u5B89\u5168\u306B\u505C\u6B62\u4E2D\u3067\u3059", "\u6B63\u5728\u5B89\u5168\u505C\u6B62", "Deteni\u00E9ndose de manera segura", "D\u1EEBng l\u1EA1i m\u1ED9t c\u00E1ch an to\u00E0n", "Berhenti dengan aman", "Parando com seguran\u00E7a", "التوقف بأمان"),
        "Storage maintenance will retry next launch." to arrayOf("Susubukan muli ang pagpapanatili ng storage sa susunod na pag-launch.", "\uC800\uC7A5\uC18C \uC720\uC9C0 \uAD00\uB9AC\uAC00 \uB2E4\uC74C \uC2E4\uD589 \uC2DC \uC7AC\uC2DC\uB3C4\uB429\uB2C8\uB2E4.", "\u30B9\u30C8\u30EC\u30FC\u30B8\u30E1\u30F3\u30C6\u30CA\u30F3\u30B9\u306F\u6B21\u56DE\u8D77\u52D5\u6642\u306B\u518D\u8A66\u884C\u3055\u308C\u307E\u3059", "\u5B58\u50A8\u7EF4\u62A4\u5C06\u5728\u4E0B\u6B21\u542F\u52A8\u65F6\u91CD\u8BD5\u3002", "El mantenimiento de almacenamiento se reintentar\u00E1 en el pr\u00F3ximo inicio.", "B\u1EA3o tr\u00EC b\u1ED9 nh\u1EDB s\u1EBD th\u1EED l\u1EA1i khi kh\u1EDFi \u0111\u1ED9ng l\u1EA7n sau.", "Pemeliharaan penyimpanan akan mencoba lagi saat peluncuran berikutnya.", "A manuten\u00E7\u00E3o de armazenamento tentar\u00E1 novamente na pr\u00F3xima inicializa\u00E7\u00E3o.", "ستعيد صيانة التخزين محاولة الإطلاق التالي."),
        "Switching safely to the verified add-on files." to arrayOf("Maingat na lumilipat sa mga na-verify na add-on files.", "\uD655\uC778\uB41C \uC560\uB4DC\uC628 \uD30C\uC77C\uB85C \uC548\uC804\uD558\uAC8C \uC804\uD658 \uC911", "\u691C\u8A3C\u6E08\u307F\u30A2\u30C9\u30AA\u30F3\u30D5\u30A1\u30A4\u30EB\u306B\u5B89\u5168\u306B\u5207\u308A\u66FF\u3048\u3066\u3044\u307E\u3059", "\u6B63\u5728\u5B89\u5168\u5207\u6362\u5230\u5DF2\u9A8C\u8BC1\u7684\u63D2\u4EF6\u6587\u4EF6\u3002", "Cambiando de manera segura a los archivos de complemento verificados.", "Chuy\u1EC3n \u0111\u1ED5i an to\u00E0n sang c\u00E1c t\u1EC7p ti\u1EC7n \u00EDch b\u1ED5 sung \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh.", "Beralih dengan aman ke file add-on yang diverifikasi.", "Mudando com seguran\u00E7a para os arquivos de complemento verificados.", "التبديل بأمان إلى ملفات الوظائف الإضافية التي تم التحقق منها."),
        "The Android installation was cancelled or could not be confirmed. The prepared package is still available." to arrayOf("Nakansela o hindi makumpirma ang pag-install sa Android. Ang inihandang package ay magagamit pa rin.", "\uC548\uB4DC\uB85C\uC774\uB4DC \uC124\uCE58\uAC00 \uCDE8\uC18C\uB418\uC5C8\uAC70\uB098 \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC900\uBE44\uB41C \uD328\uD0A4\uC9C0\uB294 \uC5EC\uC804\uD788 \uC0AC\uC6A9 \uAC00\uB2A5\uD569\uB2C8\uB2E4.", "Android\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u305F\u304B\u3001\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u6E96\u5099\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u307E\u3060\u5229\u7528\u53EF\u80FD\u3067\u3059\u3002", "\u5B89\u5353\u5B89\u88C5\u5DF2\u53D6\u6D88\u6216\u65E0\u6CD5\u786E\u8BA4\u3002\u5DF2\u51C6\u5907\u7684\u5B89\u88C5\u5305\u4ECD\u53EF\u4F7F\u7528\u3002", "La instalaci\u00F3n de Android fue cancelada o no pudo ser confirmada. El paquete preparado todav\u00EDa est\u00E1 disponible.", "Vi\u1EC7c c\u00E0i \u0111\u1EB7t Android \u0111\u00E3 b\u1ECB h\u1EE7y ho\u1EB7c kh\u00F4ng th\u1EC3 x\u00E1c nh\u1EADn. G\u00F3i \u0111\u00E3 chu\u1EA9n b\u1ECB v\u1EABn c\u00F2n s\u1EB5n c\u00F3.", "Instalasi Android dibatalkan atau tidak dapat dikonfirmasi. Paket yang telah disiapkan masih tersedia.", "A instala\u00E7\u00E3o do Android foi cancelada ou n\u00E3o p\u00F4de ser confirmada. O pacote preparado ainda est\u00E1 dispon\u00EDvel.", "تم إلغاء تثبيت Android أو تعذر تأكيده. الحزمة المعدة لا تزال متاحة."),
        "The Android installer will open after the file is verified." to arrayOf("Magbubukas ang installer ng Android pagkatapos ma-verify ang file.", "\uD30C\uC77C\uC774 \uD655\uC778\uB41C \uD6C4 \uC548\uB4DC\uB85C\uC774\uB4DC \uC124\uCE58 \uAD00\uB9AC\uC790\uAC00 \uC5F4\uB9BD\uB2C8\uB2E4.", "\u30D5\u30A1\u30A4\u30EB\u304C\u78BA\u8A8D\u3055\u308C\u305F\u5F8C\u3001Android\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u958B\u304D\u307E\u3059\u3002", "\u6587\u4EF6\u901A\u8FC7\u9A8C\u8BC1\u540E\uFF0C\u5B89\u5353\u5B89\u88C5\u7A0B\u5E8F\u5C06\u6253\u5F00\u3002", "El instalador de Android se abrir\u00E1 despu\u00E9s de que el archivo sea verificado.", "Tr\u00ECnh c\u00E0i \u0111\u1EB7t Android s\u1EBD m\u1EDF sau khi t\u1EC7p \u0111\u01B0\u1EE3c x\u00E1c minh.", "Penginstal Android akan terbuka setelah file diverifikasi.", "O instalador do Android ser\u00E1 aberto ap\u00F3s o arquivo ser verificado.", "سيتم فتح برنامج تثبيت Android بعد التحقق من الملف."),
        "The available file cannot replace your installed game version." to arrayOf("Hindi maaaring palitan ng magagamit na file ang naka-install na bersyon ng iyong laro.", "\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uD30C\uC77C\uC740 \uC124\uCE58\uB41C \uAC8C\uC784 \uBC84\uC804\uC744 \uB300\uCCB4\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u5229\u7528\u53EF\u80FD\u306A\u30D5\u30A1\u30A4\u30EB\u306F\u3001\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u306E\u30B2\u30FC\u30E0\u30D0\u30FC\u30B8\u30E7\u30F3\u3092\u7F6E\u304D\u63DB\u3048\u308B\u3053\u3068\u306F\u3067\u304D\u307E\u305B\u3093\u3002", "\u53EF\u7528\u6587\u4EF6\u4E0D\u80FD\u66FF\u6362\u4F60\u5DF2\u5B89\u88C5\u7684\u6E38\u620F\u7248\u672C\u3002", "El archivo disponible no puede reemplazar la versi\u00F3n del juego que tienes instalada.", "T\u1EC7p c\u00F3 s\u1EB5n kh\u00F4ng th\u1EC3 thay th\u1EBF phi\u00EAn b\u1EA3n tr\u00F2 ch\u01A1i \u0111\u00E3 c\u00E0i \u0111\u1EB7t c\u1EE7a b\u1EA1n.", "File yang tersedia tidak dapat menggantikan versi game yang sudah terpasang.", "O arquivo dispon\u00EDvel n\u00E3o pode substituir a vers\u00E3o do jogo que voc\u00EA instalou.", "لا يمكن للملف المتوفر أن يحل محل إصدار اللعبة المثبت لديك."),
        "The connection or service was temporarily unavailable. Any partial download is safe; try again when the connection is stable." to arrayOf("Pansamantala ang hindi magagamit ng koneksyon o serbisyo. Ligtas ang anumang bahagyang pag-download; subukang muli kapag matatag na ang koneksyon.", "\uC5F0\uACB0 \uB610\uB294 \uC11C\uBE44\uC2A4\uAC00 \uC77C\uC2DC\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC77C\uBD80 \uB2E4\uC6B4\uB85C\uB4DC\uB41C \uD30C\uC77C\uC740 \uC548\uC804\uD558\uBBC0\uB85C, \uC5F0\uACB0\uC774 \uC548\uC815\uB420 \uB54C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u63A5\u7D9A\u307E\u305F\u306F\u30B5\u30FC\u30D3\u30B9\u304C\u4E00\u6642\u7684\u306B\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u90E8\u5206\u7684\u306A\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u5B89\u5168\u3067\u3059\uFF1B\u63A5\u7D9A\u304C\u5B89\u5B9A\u3057\u305F\u3089\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u8FDE\u63A5\u6216\u670D\u52A1\u6682\u65F6\u4E0D\u53EF\u7528\u3002\u4EFB\u4F55\u90E8\u5206\u4E0B\u8F7D\u90FD\u662F\u5B89\u5168\u7684\uFF1B\u8BF7\u5728\u8FDE\u63A5\u7A33\u5B9A\u65F6\u91CD\u8BD5\u3002", "La conexi\u00F3n o el servicio estuvo temporalmente no disponible. Cualquier descarga parcial es segura; int\u00E9ntalo de nuevo cuando la conexi\u00F3n sea estable.", "K\u1EBFt n\u1ED1i ho\u1EB7c d\u1ECBch v\u1EE5 t\u1EA1m th\u1EDDi kh\u00F4ng kh\u1EA3 d\u1EE5ng. B\u1EA5t k\u1EF3 ph\u1EA7n t\u1EA3i xu\u1ED1ng n\u00E0o c\u0169ng an to\u00E0n; h\u00E3y th\u1EED l\u1EA1i khi k\u1EBFt n\u1ED1i \u1ED5n \u0111\u1ECBnh.", "Koneksi atau layanan sementara tidak tersedia. Setiap unduhan sebagian aman; coba lagi saat koneksi stabil.", "A conex\u00E3o ou servi\u00E7o estava temporariamente indispon\u00EDvel. Qualquer download parcial est\u00E1 seguro; tente novamente quando a conex\u00E3o estiver est\u00E1vel.", "لم يكن الاتصال أو الخدمة متاحين مؤقتًا. يعتبر أي تنزيل جزئي آمنًا؛ حاول مرة أخرى عندما يكون الاتصال مستقرًا."),
        "The digital key could not be accepted. Please start a fresh unlock and try again." to arrayOf("Hindi matanggap ang digital key. Mangyaring magsimula ng bagong unlock at subukang muli.", "\uB514\uC9C0\uD138 \uD0A4\uB97C \uC218\uB77D\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC0C8\uB85C \uC7A0\uAE08 \uD574\uC81C\uB97C \uC2DC\uC791\uD558\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30C7\u30B8\u30BF\u30EB\u30AD\u30FC\u3092\u53D7\u3051\u4ED8\u3051\u308B\u3053\u3068\u304C\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u65B0\u3057\u3044\u30A2\u30F3\u30ED\u30C3\u30AF\u3092\u958B\u59CB\u3057\u3066\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u65E0\u6CD5\u63A5\u53D7\u6570\u5B57\u5BC6\u94A5\u3002\u8BF7\u91CD\u65B0\u5F00\u59CB\u89E3\u9501\u5E76\u91CD\u8BD5\u3002", "La clave digital no pudo ser aceptada. Por favor, inicia un desbloqueo nuevo e int\u00E9ntalo de nuevo.", "Kh\u00F3a k\u1EF9 thu\u1EADt s\u1ED1 kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c ch\u1EA5p nh\u1EADn. Vui l\u00F2ng b\u1EAFt \u0111\u1EA7u m\u1EDF kh\u00F3a m\u1EDBi v\u00E0 th\u1EED l\u1EA1i.", "Kunci digital tidak dapat diterima. Silakan mulai membuka kunci baru dan coba lagi.", "A chave digital n\u00E3o p\u00F4de ser aceita. Por favor, inicie um desbloqueio novo e tente novamente.", "لا يمكن قبول المفتاح الرقمي. يرجى بدء فتح جديد والمحاولة مرة أخرى."),
        "The downloaded file did not match its trusted release details, so it was not activated. Retry to obtain a clean copy." to arrayOf("Ang na-download na file ay hindi tumugma sa mga detalyeng pinagtitiwalaang release, kaya hindi ito na-activate. Subukang muli upang makakuha ng malinis na kopya.", "\uB2E4\uC6B4\uB85C\uB4DC\uB41C \uD30C\uC77C\uC774 \uC2E0\uB8B0\uB41C \uB9B4\uB9AC\uC2A4 \uC815\uBCF4\uC640 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC544 \uD65C\uC131\uD654\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uAE68\uB057\uD55C \uBCF5\uC0AC\uBCF8\uC744 \uC5BB\uAE30 \uC704\uD574 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3057\u305F\u30D5\u30A1\u30A4\u30EB\u306F\u4FE1\u983C\u3055\u308C\u305F\u30EA\u30EA\u30FC\u30B9\u8A73\u7D30\u3068\u4E00\u81F4\u3057\u306A\u304B\u3063\u305F\u305F\u3081\u3001\u30A2\u30AF\u30C6\u30A3\u30D9\u30FC\u30C8\u3055\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30AF\u30EA\u30FC\u30F3\u306A\u30B3\u30D4\u30FC\u3092\u53D6\u5F97\u3059\u308B\u305F\u3081\u306B\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u4E0B\u8F7D\u7684\u6587\u4EF6\u4E0E\u5176\u53EF\u4FE1\u53D1\u884C\u8BE6\u60C5\u4E0D\u5339\u914D\uFF0C\u56E0\u6B64\u672A\u6FC0\u6D3B\u3002\u8BF7\u91CD\u8BD5\u4EE5\u83B7\u53D6\u5E72\u51C0\u7684\u526F\u672C\u3002", "El archivo descargado no coincidi\u00F3 con los detalles de su versi\u00F3n confiable, por lo que no fue activado. Reintenta para obtener una copia limpia.", "T\u1EC7p \u0111\u00E3 t\u1EA3i xu\u1ED1ng kh\u00F4ng kh\u1EDBp v\u1EDBi chi ti\u1EBFt ph\u00E1t h\u00E0nh \u0111\u00E1ng tin c\u1EADy c\u1EE7a n\u00F3, n\u00EAn kh\u00F4ng \u0111\u01B0\u1EE3c k\u00EDch ho\u1EA1t. H\u00E3y th\u1EED l\u1EA1i \u0111\u1EC3 c\u00F3 b\u1EA3n sao s\u1EA1ch.", "File yang diunduh tidak cocok dengan detail rilis yang terpercaya, sehingga tidak diaktifkan. Coba lagi untuk mendapatkan salinan yang bersih.", "O arquivo baixado n\u00E3o correspondeu aos detalhes confi\u00E1veis de lan\u00E7amento, portanto n\u00E3o foi ativado. Tente novamente para obter uma c\u00F3pia limpa.", "الملف الذي تم تنزيله لم يتطابق مع تفاصيل الإصدار الموثوق به، لذلك لم يتم تنشيطه. أعد المحاولة للحصول على نسخة نظيفة."),
        "The embedded private add-on can only be updated by installing a new signed launcher build that contains it." to arrayOf("Ang naka-embed na pribadong add-on ay maaring ma-update lamang sa pamamagitan ng pag-install ng bagong signed launcher build na naglalaman nito.", "\uB0B4\uC7A5\uB41C \uAC1C\uC778 \uCD94\uAC00 \uAE30\uB2A5\uC740 \uC774\uB97C \uD3EC\uD568\uD55C \uC0C8\uB85C\uC6B4 \uC11C\uBA85\uB41C \uB7F0\uCC98 \uBE4C\uB4DC\uB97C \uC124\uCE58\uD574\uC57C\uB9CC \uC5C5\uB370\uC774\uD2B8\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u57CB\u3081\u8FBC\u307E\u308C\u305F\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30A2\u30C9\u30AA\u30F3\u306F\u3001\u305D\u308C\u3092\u542B\u3080\u65B0\u3057\u3044\u7F72\u540D\u4ED8\u304D\u30E9\u30F3\u30C1\u30E3\u30FC\u30D3\u30EB\u30C9\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3059\u308B\u3053\u3068\u3067\u306E\u307F\u66F4\u65B0\u3067\u304D\u307E\u3059\u3002", "\u5D4C\u5165\u7684\u79C1\u6709\u63D2\u4EF6\u53EA\u80FD\u901A\u8FC7\u5B89\u88C5\u5305\u542B\u5B83\u7684\u65B0\u7B7E\u540D\u542F\u52A8\u5668\u7248\u672C\u6765\u66F4\u65B0\u3002", "El complemento privado incrustado solo puede actualizarse instalando una nueva versi\u00F3n del lanzador firmado que lo contenga.", "Ti\u1EC7n \u00EDch b\u1ED5 sung ri\u00EAng t\u00EDch h\u1EE3p ch\u1EC9 c\u00F3 th\u1EC3 \u0111\u01B0\u1EE3c c\u1EADp nh\u1EADt b\u1EB1ng c\u00E1ch c\u00E0i \u0111\u1EB7t phi\u00EAn b\u1EA3n launcher m\u1EDBi c\u00F3 ch\u1EEF k\u00FD ch\u1EE9a n\u00F3.", "Add-on pribadi tersemat hanya dapat diperbarui dengan menginstal versi launcher baru yang sudah ditandatangani yang memuatnya.", "O complemento privado incorporado s\u00F3 pode ser atualizado instalando uma nova vers\u00E3o do launcher assinada que o contenha.", "لا يمكن تحديث الوظيفة الإضافية الخاصة المضمنة إلا عن طريق تثبيت إصدار مشغل موقع جديد يحتوي عليها."),
        "The game wasn't installed" to arrayOf("Hindi na-install ang laro", "\uAC8C\uC784\uC774 \uC124\uCE58\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4", "\u30B2\u30FC\u30E0\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3067\u3057\u305F", "\u6E38\u620F\u672A\u5B89\u88C5", "El juego no estaba instalado", "Tr\u00F2 ch\u01A1i ch\u01B0a \u0111\u01B0\u1EE3c c\u00E0i \u0111\u1EB7t", "Game belum diinstal", "O jogo n\u00E3o foi instalado", "لم يتم تثبيت اللعبة"),
        "The game-branded shell is ready. Open it here or directly from your home screen." to arrayOf("Ang shell na may tatak ng laro ay handa na. Buksan ito dito o direkta mula sa iyong home screen.", "\uAC8C\uC784 \uBE0C\uB79C\uB4DC \uC140\uC774 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC5EC\uAE30\uC5D0\uC11C \uC5F4\uAC70\uB098 \uD648 \uD654\uBA74\uC5D0\uC11C \uC9C1\uC811 \uC5F4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u30B2\u30FC\u30E0\u30D6\u30E9\u30F3\u30C9\u306E\u30B7\u30A7\u30EB\u304C\u6E96\u5099\u3067\u304D\u307E\u3057\u305F\u3002\u3053\u3053\u3067\u958B\u304F\u304B\u3001\u30DB\u30FC\u30E0\u753B\u9762\u304B\u3089\u76F4\u63A5\u958B\u3044\u3066\u304F\u3060\u3055\u3044\u3002", "\u6E38\u620F\u54C1\u724C\u5916\u58F3\u5DF2\u51C6\u5907\u597D\u3002\u53EF\u5728\u6B64\u6253\u5F00\u6216\u76F4\u63A5\u4ECE\u4E3B\u5C4F\u5E55\u6253\u5F00\u3002", "La aplicaci\u00F3n con marca del juego est\u00E1 lista. \u00C1brela aqu\u00ED o directamente desde tu pantalla de inicio.", "V\u1ECF tr\u00F2 ch\u01A1i \u0111\u00E3 s\u1EB5n s\u00E0ng. M\u1EDF \u1EDF \u0111\u00E2y ho\u1EB7c tr\u1EF1c ti\u1EBFp t\u1EEB m\u00E0n h\u00ECnh ch\u00EDnh c\u1EE7a b\u1EA1n.", "Shell berlabel permainan sudah siap. Buka di sini atau langsung dari layar utama Anda.", "O shell com marca do jogo est\u00E1 pronto. Abra-o aqui ou diretamente da sua tela inicial.", "الغلاف الذي يحمل علامة اللعبة جاهز. افتحه هنا أو مباشرة من شاشتك الرئيسية."),
        "The installation wasn't completed. The verified download is still saved; tap Try again." to arrayOf("Hindi natapos ang pag-install. Ang beripikadong download ay nakasave pa rin; i-tap ang Subukang muli.", "\uC124\uCE58\uAC00 \uC644\uB8CC\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uD655\uC778\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uC544\uC9C1 \uC800\uC7A5\uB418\uC5B4 \uC788\uC73C\uBBC0\uB85C, \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uB824\uBA74 '\uB2E4\uC2DC \uC2DC\uB3C4'\uB97C \uB204\uB974\uC138\uC694.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u5B8C\u4E86\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u78BA\u8A8D\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u307E\u3060\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u3059\u3002[\u518D\u8A66\u884C]\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5B89\u88C5\u672A\u5B8C\u6210\u3002\u5DF2\u9A8C\u8BC1\u7684\u4E0B\u8F7D\u4ECD\u7136\u4FDD\u5B58\uFF1B\u70B9\u51FB\u91CD\u8BD5\u3002", "La instalaci\u00F3n no se complet\u00F3. La descarga verificada todav\u00EDa est\u00E1 guardada; toca Intentar de nuevo.", "Vi\u1EC7c c\u00E0i \u0111\u1EB7t ch\u01B0a ho\u00E0n t\u1EA5t. T\u1EC7p t\u1EA3i xu\u1ED1ng \u0111\u00E3 x\u00E1c minh v\u1EABn \u0111\u01B0\u1EE3c l\u01B0u; ch\u1EA1m Th\u1EED l\u1EA1i.", "Instalasi tidak selesai. Unduhan yang sudah diverifikasi masih tersimpan; ketuk Coba lagi.", "A instala\u00E7\u00E3o n\u00E3o foi conclu\u00EDda. O download verificado ainda est\u00E1 salvo; toque em Tentar novamente.", "لم يكتمل التثبيت. لا يزال التنزيل الذي تم التحقق منه محفوظًا؛ اضغط على حاول مرة أخرى."),
        "The latest version" to arrayOf("Ang pinakabagong bersyon", "\uCD5C\uC2E0 \uBC84\uC804", "\u6700\u65B0\u30D0\u30FC\u30B8\u30E7\u30F3", "\u6700\u65B0\u7248\u672C", "La \u00FAltima versi\u00F3n", "Phi\u00EAn b\u1EA3n m\u1EDBi nh\u1EA5t", "Versi terbaru", "A vers\u00E3o mais recente", "أحدث نسخة"),
    )
}
